#define main legacy_main
#include "../entropy-cuda/main.cu"
#undef main
#include <vector>
#include <string>
#include <algorithm>
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;const int w=131,h=97,n=w*h;std::vector<char>a(3*n);srand(123);for(int i=0;i<n;i++){a[i]=rand()%16;a[n+i]=7;a[2*n+i]=((i%w)+3*(i/w))%16;}
float table[26];for(int k=0;k<=25;k++)table[k]=k<=1?0:k*log2f(k);std::vector<double>gold(3*n);for(int f=0;f<3;f++)for(int y=0;y<h;y++)for(int x=0;x<w;x++){int count[16]={},total=0;for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int xx=x+dx,yy=y+dy;if(xx>=0&&xx<w&&yy>=0&&yy<h){count[(int)a[f*n+yy*w+xx]]++;total++;}}double s=0;for(int k=0;k<16;k++)if(count[k]){double p=(double)count[k]/total;s-=p*log2(p);}gold[f*n+y*w+x]=s;}
char*da;float*dt,*out;cudaMalloc(&da,3*n);cudaMalloc(&dt,sizeof(table));cudaMalloc(&out,3*n*4);cudaMemcpy(da,a.data(),3*n,cudaMemcpyHostToDevice);cudaMemcpy(dt,table,sizeof(table),cudaMemcpyHostToDevice);cudaMemset(out,0xff,3*n*4);dim3 block(16,16),grid((w+15)/16,(h+15)/16);
// Untimed untouched baseline witness: absent histogram bins produce 0*log2(0).
entropy<<<grid,block>>>(out,da,h,w);cudaDeviceSynchronize();std::vector<float>probe(n);cudaMemcpy(probe.data(),out,n*4,cudaMemcpyDeviceToHost);int nans=0;for(float x:probe)nans+=std::isnan(x);printf("STUDY_BASELINE_WITNESS {\"untouched_baseline_nan_pixels\":%d,\"corner_expected_finite\":true}\n",nans);if(!nans)return 3;
for(int f=0;f<3;f++)entropy_opt<16,16><<<grid,block>>>(out+f*n,da+f*n,dt,h,w);cudaDeviceSynchronize();
for(int trial=1;trial<=5;trial++){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)for(int f=0;f<3;f++)entropy_opt<16,16><<<grid,block>>>(out+f*n,da+f*n,dt,h,w);cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/repeat;std::vector<float>got(3*n),artifact;cudaMemcpy(got.data(),out,3*n*4,cudaMemcpyDeviceToHost);double err=0;bool ok=cudaGetLastError()==cudaSuccess;for(int i=0;i<3*n;i++){double e=fabs(got[i]-gold[i]);err=std::max(err,e);ok&=std::isfinite(got[i])&&e<1e-5&&got[i]>=-1e-6&&got[i]<=4.00001;}for(int i=n;i<2*n;i++)ok&=fabs(got[i])<1e-6;for(char v:a)artifact.push_back((float)v);artifact.insert(artifact.end(),table,table+26);artifact.insert(artifact.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(artifact.data(),4,artifact.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.17g,\"max_rel_error\":0.0,\"timing_region\":\"three_complete_optimized_entropy_kernels\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",3*n,err,repeat,path.c_str(),artifact.size());if(!ok)return 2;}cudaFree(da);cudaFree(dt);cudaFree(out);}
